{
  "summary": "You can apply for your HFE letter now and use it for a BTO launch occurring within the next 12 months, but ensure the letter remains valid at the time you submit your BTO application.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "An HFE (Housing Flat Eligibility) letter is valid for 12 months from the date it is issued."
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "You must have a valid HFE letter at the time you submit your BTO application; the letter does not need to be issued on the exact day of the ballot."
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Apply for your HFE letter now via the HDB Flat Portal; note the issue date on the letter."
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Mark your calendar for the expected BTO launch in October 2027 and ensure the HFE issue date is before October 2027 and not earlier than 12 months prior to your intended application date."
    },
    {
      "claim_id": "c5",
      "kind": "caveat",
      "text": "If the BTO launch you plan to apply for occurs after the 12‑month validity window, you will need to re‑apply for a new HFE letter."
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}
